void ecm_vtacho_engine_status( Boolean runningOrNot )
{
	ATOMIC(ecm_vtacho_vars.running = runningOrNot);
}		

/*--------------------------------------------------------------------------*/

Boolean ecm_vtacho_engine_started_by_user(void)
{
    if(ecm_vtacho_vars.v_ign_on > get_voltage() )
    {
        if((ecm_vtacho_vars.v_ign_on > get_voltage())>ECM_VTACHO_VOLTAGE_ENGINE_STARTED_BY_USER_DIFF)
        {
            TRACE_DEI_ECM("[ECM_VTACHO_ENGINE_STARTED_BY_USER]\n\r");	

            return TRUE;
        }        
    }

    TRACE_DEI_ECM("[ECM_VTACHO_ENGINE_NOT_RUNNING]\n\r");	
    
    return FALSE;    
}

